use split_decls_genesis :: ourprelude :: * ; use std :: cmp :: Ordering ; use std :: ops :: { Index , IndexMut } ; use std :: { mem , slice } ; use rustc_data_structures :: fx :: FxHashSet ; use rustc_data_structures :: graph :: dominators :: Dominators ; use rustc_data_structures :: graph :: { self , DirectedGraph , StartNode } ; use rustc_index :: IndexVec ; use rustc_index :: bit_set :: DenseBitSet ; pub (crate) use rustc_middle :: mir :: coverage :: { BasicCoverageBlock , START_BCB } ; use rustc_middle :: mir :: { self , BasicBlock , Terminator , TerminatorKind } ; use tracing :: debug ; #[doc = " A coverage-specific simplification of the MIR control flow graph (CFG). The `CoverageGraph`s"] #[doc = " nodes are `BasicCoverageBlock`s, which encompass one or more MIR `BasicBlock`s."] #[derive (Debug)] pub (crate) struct CoverageGraph { bcbs : IndexVec < BasicCoverageBlock , BasicCoverageBlockData > , bb_to_bcb : IndexVec < BasicBlock , Option < BasicCoverageBlock > > , pub (crate) successors : IndexVec < BasicCoverageBlock , Vec < BasicCoverageBlock > > , pub (crate) predecessors : IndexVec < BasicCoverageBlock , Vec < BasicCoverageBlock > > , dominators : Option < Dominators < BasicCoverageBlock > > , #[doc = " Allows nodes to be compared in some total order such that _if_"] #[doc = " `a` dominates `b`, then `a < b`. If neither node dominates the other,"] #[doc = " their relative order is consistent but arbitrary."] dominator_order_rank : IndexVec < BasicCoverageBlock , u32 > , #[doc = " A loop header is a node that dominates one or more of its predecessors."] is_loop_header : DenseBitSet < BasicCoverageBlock > , #[doc = " For each node, the loop header node of its nearest enclosing loop."] #[doc = " This forms a linked list that can be traversed to find all enclosing loops."] enclosing_loop_header : IndexVec < BasicCoverageBlock , Option < BasicCoverageBlock > > , } impl CoverageGraph { pub (crate) fn from_mir (mir_body : & mir :: Body < '_ >) -> Self { let (bcbs , bb_to_bcb) = Self :: compute_basic_coverage_blocks (mir_body) ; let successors = IndexVec :: < BasicCoverageBlock , _ > :: from_fn_n (| bcb | { let mut seen_bcbs = FxHashSet :: default () ; let terminator = mir_body [bcbs [bcb] . last_bb ()] . terminator () ; bcb_filtered_successors (terminator) . into_iter () . filter_map (| successor_bb | bb_to_bcb [successor_bb]) . filter (| & successor_bcb | seen_bcbs . insert (successor_bcb)) . collect :: < Vec < _ > > () } , bcbs . len () ,) ; let mut predecessors = IndexVec :: from_elem (Vec :: new () , & bcbs) ; for (bcb , bcb_successors) in successors . iter_enumerated () { for & successor in bcb_successors { predecessors [successor] . push (bcb) ; } } let num_nodes = bcbs . len () ; let mut this = Self { bcbs , bb_to_bcb , successors , predecessors , dominators : None , dominator_order_rank : IndexVec :: from_elem_n (0 , num_nodes) , is_loop_header : DenseBitSet :: new_empty (num_nodes) , enclosing_loop_header : IndexVec :: from_elem_n (None , num_nodes) , } ; assert_eq ! (num_nodes , this . num_nodes ()) ; this . dominators = Some (graph :: dominators :: dominators (& this)) ; let dominator_order = graph :: iterate :: reverse_post_order (& this , this . start_node ()) ; assert_eq ! (dominator_order . len () , this . num_nodes ()) ; for (rank , bcb) in (0u32 ..) . zip (dominator_order) { this . dominator_order_rank [bcb] = rank ; if this . reloop_predecessors (bcb) . next () . is_some () { this . is_loop_header . insert (bcb) ; } if let Some (dom) = this . dominators () . immediate_dominator (bcb) { this . enclosing_loop_header [bcb] = this . is_loop_header . contains (dom) . then_some (dom) . or_else (| | this . enclosing_loop_header [dom]) ; } } assert ! (this [START_BCB] . leader_bb () == mir :: START_BLOCK) ; assert ! (this . predecessors [START_BCB] . is_empty ()) ; this } fn compute_basic_coverage_blocks (mir_body : & mir :: Body < '_ > ,) -> (IndexVec < BasicCoverageBlock , BasicCoverageBlockData > , IndexVec < BasicBlock , Option < BasicCoverageBlock > > ,) { let num_basic_blocks = mir_body . basic_blocks . len () ; let mut bcbs = IndexVec :: < BasicCoverageBlock , _ > :: with_capacity (num_basic_blocks) ; let mut bb_to_bcb = IndexVec :: from_elem_n (None , num_basic_blocks) ; let mut flush_chain_into_new_bcb = | current_chain : & mut Vec < BasicBlock > | { let basic_blocks = mem :: take (current_chain) ; let bcb = bcbs . next_index () ; for & bb in basic_blocks . iter () { bb_to_bcb [bb] = Some (bcb) ; } let is_out_summable = basic_blocks . last () . is_some_and (| & bb | { bcb_filtered_successors (mir_body [bb] . terminator ()) . is_out_summable () }) ; let bcb_data = BasicCoverageBlockData { basic_blocks , is_out_summable } ; debug ! ("adding {bcb:?}: {bcb_data:?}") ; bcbs . push (bcb_data) ; } ; let mut current_chain = vec ! [] ; let subgraph = CoverageRelevantSubgraph :: new (& mir_body . basic_blocks) ; for bb in graph :: depth_first_search (subgraph , mir :: START_BLOCK) . filter (| & bb | mir_body [bb] . terminator () . kind != TerminatorKind :: Unreachable) { if let Some (& prev) = current_chain . last () { let can_chain = subgraph . coverage_successors (prev) . is_out_chainable () && mir_body . basic_blocks . predecessors () [bb] . as_slice () == & [prev] ; if ! can_chain { flush_chain_into_new_bcb (& mut current_chain) ; } } current_chain . push (bb) ; } if ! current_chain . is_empty () { debug ! ("flushing accumulated blocks into one last BCB") ; flush_chain_into_new_bcb (& mut current_chain) ; } (bcbs , bb_to_bcb) } #[inline (always)] pub (crate) fn iter_enumerated (& self ,) -> impl Iterator < Item = (BasicCoverageBlock , & BasicCoverageBlockData) > { self . bcbs . iter_enumerated () } #[inline (always)] pub (crate) fn bcb_from_bb (& self , bb : BasicBlock) -> Option < BasicCoverageBlock > { if bb . index () < self . bb_to_bcb . len () { self . bb_to_bcb [bb] } else { None } } #[inline (always)] fn dominators (& self) -> & Dominators < BasicCoverageBlock > { self . dominators . as_ref () . unwrap () } #[inline (always)] pub (crate) fn dominates (& self , dom : BasicCoverageBlock , node : BasicCoverageBlock) -> bool { self . dominators () . dominates (dom , node) } #[inline (always)] pub (crate) fn cmp_in_dominator_order (& self , a : BasicCoverageBlock , b : BasicCoverageBlock ,) -> Ordering { self . dominator_order_rank [a] . cmp (& self . dominator_order_rank [b]) } #[doc = " For the given node, yields the subset of its predecessor nodes that"] #[doc = " it dominates. If that subset is non-empty, the node is a \"loop header\","] #[doc = " and each of those predecessors represents an in-edge that jumps back to"] #[doc = " the top of its loop."] pub (crate) fn reloop_predecessors (& self , to_bcb : BasicCoverageBlock ,) -> impl Iterator < Item = BasicCoverageBlock > { self . predecessors [to_bcb] . iter () . copied () . filter (move | & pred | self . dominates (to_bcb , pred)) } } impl Index < BasicCoverageBlock > for CoverageGraph { type Output = BasicCoverageBlockData ; #[inline] fn index (& self , index : BasicCoverageBlock) -> & BasicCoverageBlockData { & self . bcbs [index] } } impl IndexMut < BasicCoverageBlock > for CoverageGraph { #[inline] fn index_mut (& mut self , index : BasicCoverageBlock) -> & mut BasicCoverageBlockData { & mut self . bcbs [index] } } impl graph :: DirectedGraph for CoverageGraph { type Node = BasicCoverageBlock ; #[inline] fn num_nodes (& self) -> usize { self . bcbs . len () } } impl graph :: StartNode for CoverageGraph { #[inline] fn start_node (& self) -> Self :: Node { self . bcb_from_bb (mir :: START_BLOCK) . expect ("mir::START_BLOCK should be in a BasicCoverageBlock") } } impl graph :: Successors for CoverageGraph { #[inline] fn successors (& self , node : Self :: Node) -> impl Iterator < Item = Self :: Node > { self . successors [node] . iter () . copied () } } impl graph :: Predecessors for CoverageGraph { #[inline] fn predecessors (& self , node : Self :: Node) -> impl Iterator < Item = Self :: Node > { self . predecessors [node] . iter () . copied () } } #[doc = " `BasicCoverageBlockData` holds the data indexed by a `BasicCoverageBlock`."] #[doc = ""] #[doc = " A `BasicCoverageBlock` (BCB) represents the maximal-length sequence of MIR `BasicBlock`s without"] #[doc = " conditional branches, and form a new, simplified, coverage-specific Control Flow Graph, without"] #[doc = " altering the original MIR CFG."] #[doc = ""] #[doc = " Note that running the MIR `SimplifyCfg` transform is not sufficient (and therefore not"] #[doc = " necessary). The BCB-based CFG is a more aggressive simplification. For example:"] #[doc = ""] #[doc = "   * The BCB CFG ignores (trims) branches not relevant to coverage, such as unwind-related code,"] #[doc = "     that is injected by the Rust compiler but has no physical source code to count. This also"] #[doc = "     means a BasicBlock with a `Call` terminator can be merged into its primary successor target"] #[doc = "     block, in the same BCB. (But, note: Issue #78544: \"MIR InstrumentCoverage: Improve coverage"] #[doc = "     of `#[should_panic]` tests and `catch_unwind()` handlers\")"] #[doc = "   * Some BasicBlock terminators support Rust-specific concerns--like borrow-checking--that are"] #[doc = "     not relevant to coverage analysis. `FalseUnwind`, for example, can be treated the same as"] #[doc = "     a `Goto`, and merged with its successor into the same BCB."] #[doc = ""] #[doc = " Each BCB with at least one computed coverage span will have no more than one `Counter`."] #[doc = " In some cases, a BCB's execution count can be computed by `Expression`. Additional"] #[doc = " disjoint coverage spans in a BCB can also be counted by `Expression` (by adding `ZERO`"] #[doc = " to the BCB's primary counter or expression)."] #[doc = ""] #[doc = " The BCB CFG is critical to simplifying the coverage analysis by ensuring graph path-based"] #[doc = " queries (`dominates()`, `predecessors`, `successors`, etc.) have branch (control flow)"] #[doc = " significance."] #[derive (Debug , Clone)] pub (crate) struct BasicCoverageBlockData { pub (crate) basic_blocks : Vec < BasicBlock > , #[doc = " If true, this node's execution count can be assumed to be the sum of the"] #[doc = " execution counts of all of its **out-edges** (assuming no panics)."] #[doc = ""] #[doc = " Notably, this is false for a node ending with [`TerminatorKind::Yield`],"] #[doc = " because the yielding coroutine might not be resumed."] pub (crate) is_out_summable : bool , } impl BasicCoverageBlockData { #[inline (always)] pub (crate) fn leader_bb (& self) -> BasicBlock { self . basic_blocks [0] } #[inline (always)] pub (crate) fn last_bb (& self) -> BasicBlock { * self . basic_blocks . last () . unwrap () } } #[doc = " Holds the coverage-relevant successors of a basic block's terminator, and"] #[doc = " indicates whether that block can potentially be combined into the same BCB"] #[doc = " as its sole successor."] #[derive (Clone , Copy , Debug)] struct CoverageSuccessors < 'a > { #[doc = " Coverage-relevant successors of the corresponding terminator."] #[doc = " There might be 0, 1, or multiple targets."] targets : & 'a [BasicBlock] , #[doc = " `Yield` terminators are not chainable, because their sole out-edge is"] #[doc = " only followed if/when the generator is resumed after the yield."] is_yield : bool , } impl CoverageSuccessors < '_ > { #[doc = " If `false`, this terminator cannot be chained into another block when"] #[doc = " building the coverage graph."] fn is_out_chainable (& self) -> bool { self . is_out_summable () && self . targets . len () == 1 } #[doc = " Returns true if the terminator itself is assumed to have the same"] #[doc = " execution count as the sum of its out-edges (assuming no panics)."] fn is_out_summable (& self) -> bool { ! self . is_yield && ! self . targets . is_empty () } } impl IntoIterator for CoverageSuccessors < '_ > { type Item = BasicBlock ; type IntoIter = impl DoubleEndedIterator < Item = Self :: Item > ; fn into_iter (self) -> Self :: IntoIter { self . targets . iter () . copied () } } fn bcb_filtered_successors < 'a , 'tcx > (terminator : & 'a Terminator < 'tcx >) -> CoverageSuccessors < 'a > { use TerminatorKind :: * ; let mut is_yield = false ; let targets = match & terminator . kind { SwitchInt { targets , .. } => targets . all_targets () , Yield { resume , .. } => { is_yield = true ; slice :: from_ref (resume) } Assert { target , .. } | Drop { target , .. } | FalseEdge { real_target : target , .. } | FalseUnwind { real_target : target , .. } | Goto { target } => slice :: from_ref (target) , Call { target : maybe_target , .. } => maybe_target . as_slice () , InlineAsm { targets , .. } => & targets , CoroutineDrop | Return | TailCall { .. } | Unreachable | UnwindResume | UnwindTerminate (_) => & [] , } ; CoverageSuccessors { targets , is_yield } } #[doc = " Wrapper around a [`mir::BasicBlocks`] graph that restricts each node's"] #[doc = " successors to only the ones considered \"relevant\" when building a coverage"] #[doc = " graph."] #[derive (Clone , Copy)] struct CoverageRelevantSubgraph < 'a , 'tcx > { basic_blocks : & 'a mir :: BasicBlocks < 'tcx > , } impl < 'a , 'tcx > CoverageRelevantSubgraph < 'a , 'tcx > { fn new (basic_blocks : & 'a mir :: BasicBlocks < 'tcx >) -> Self { Self { basic_blocks } } fn coverage_successors (& self , bb : BasicBlock) -> CoverageSuccessors < '_ > { bcb_filtered_successors (self . basic_blocks [bb] . terminator ()) } } impl < 'a , 'tcx > graph :: DirectedGraph for CoverageRelevantSubgraph < 'a , 'tcx > { type Node = BasicBlock ; fn num_nodes (& self) -> usize { self . basic_blocks . num_nodes () } } impl < 'a , 'tcx > graph :: Successors for CoverageRelevantSubgraph < 'a , 'tcx > { fn successors (& self , bb : Self :: Node) -> impl Iterator < Item = Self :: Node > { self . coverage_successors (bb) . into_iter () } }